$py=@'
import json,re,sqlite3,gzip,urllib.request,pathlib
headers={'User-Agent':'nai-v5-studio-personal/1.0'}
slugs=['sex','tag_group:sex_acts','tag_group:sexual_positions']
all_names=set()
for slug in slugs:
    url='https://danbooru.donmai.us/wiki_pages/'+urllib.parse.quote(slug,safe='')+'.json'
    req=urllib.request.Request(url,headers=headers)
    with urllib.request.urlopen(req,timeout=30) as response:
        page=json.load(response)
    for name in re.findall(r'\[\[([^\]|#]+)', page.get('body','')):
        name=name.strip()
        if name and not name.lower().startswith('tag group:') and name.lower()!='tag groups':
            all_names.add(name)
def norm(s):
    return re.sub(r'\s+',' ',s.replace('_',' ').replace('\\(','(').replace('\\)',')').strip().lower())
def disp(s):
    return s.replace('\\(','(').replace('\\)',')').replace('_',' ')
gz=pathlib.Path('src-tauri/resources/danbooru.sqlite.gz')
tmp=pathlib.Path('.agent/danbooru-sex-build.sqlite')
with gzip.open(gz,'rb') as src, tmp.open('wb') as dst: dst.write(src.read())
con=sqlite3.connect(tmp)
rows=con.execute('select raw,category,count from tags').fetchall()
idx={norm(raw):(raw,category,count) for raw,category,count in rows}
out=[]
for name in sorted(all_names,key=str.lower):
    row=idx.get(norm(name))
    if row and row[1]==0:
        out.append({'raw':row[0],'display':disp(row[0]),'count':int(row[2])})
    elif not row:
        out.append({'raw':name,'display':name,'count':0})
con.close(); tmp.unlink(missing_ok=True)
seen=set(); unique=[]
for item in sorted(out,key=lambda x:(-x['count'],x['display'].lower())):
    key=norm(item['raw'])
    if key in seen: continue
    seen.add(key); unique.append(item)
payload={'source':'Danbooru wiki: sex + tag_group:sex_acts + tag_group:sexual_positions','generated':'2026-08-26','tags':unique}
path=pathlib.Path('public/data/sexual-tags.json'); path.parent.mkdir(parents=True,exist_ok=True); path.write_text(json.dumps(payload,ensure_ascii=False,separators=(',',':'))+'\n',encoding='utf-8')
print('TAG_COUNT='+str(len(unique)))
print('MISSING_COUNT='+str(sum(1 for x in unique if x['count']==0)))
print('SIZE='+str(path.stat().st_size))
'@; $pyPath=Join-Path $env:TEMP 'nai_bundle_sex_tags.py'; Set-Content $pyPath $py -Encoding UTF8; python $pyPath; if($LASTEXITCODE -ne 0){exit $LASTEXITCODE}; Remove-Item $pyPath -Force -ErrorAction SilentlyContinue
